using System;using System.Collections.Generic;using System.Linq;using HabitatShift.Core;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public sealed class R10SearchNode {public RuntimeState state;public string hash;public R10SearchNode parent;public R10MacroMove move;public int depth,score;}
public static class R10BeamSolver { public static string StateHash(RuntimeState s){return (s.won?"W|":"L|")+string.Join("|",s.habitats.OrderBy(x=>x.id).Select(x=>x.id+":"+x.anchor.x.ToString("F3")+","+x.anchor.y.ToString("F3")+":"+x.stageIndex+":"+x.ActiveRemaining).Concat(s.sprouts.OrderBy(x=>x.id).Select(x=>x.id+":"+x.color+":"+x.position.x.ToString("F3")+","+x.position.y.ToString("F3"))).Concat(s.elevators.OrderBy(x=>x.id).Select(x=>x.id+":"+x.nextIndex)));}
 static int Score(RuntimeState s,int initialSprouts){var stages=s.habitats.Sum(h=>h.ActiveRemaining);var queue=s.elevators.Sum(e=>e.queue.Count-e.nextIndex);return (initialSprouts-s.sprouts.Count)*100-stages*10-queue*2+(s.won?100000:0);}
 public static R10Candidate Solve(R10Candidate c,RulesetDto rules,int width,int limit){var initial=ContinuousSession.Initial(c.project.level);var root=new R10SearchNode{state=initial,hash=StateHash(initial),depth=0,score=Score(initial,initial.sprouts.Count)};var frontier=new List<R10SearchNode>{root};var visited=new HashSet<string>{root.hash};var nodes=0;R10SearchNode win=null;while(frontier.Count>0&&nodes<limit&&win==null){var next=new List<R10SearchNode>();foreach(var n in frontier){foreach(var m in R10MacroMoves.Enumerate(c.project.level,rules,n.state)){nodes++;var hash=StateHash(m.result);if(!visited.Add(hash))continue;var risk=R10Deadlock.AnalyzeState(c.project.level,rules,m.result);if(risk==R10Risk.PROVEN_DEADLOCK)continue;var child=new R10SearchNode{state=m.result,hash=hash,parent=n,move=m,depth=n.depth+1,score=Score(m.result,initial.sprouts.Count)-(risk==R10Risk.HIGH_RISK?5:0)};if(child.state.won){win=child;break;}next.Add(child);if(nodes>=limit)break;}if(win!=null||nodes>=limit)break;}frontier=next.OrderByDescending(x=>x.score).ThenBy(x=>x.hash).Take(Math.Max(1,width)).ToList();}
 if(win==null){c.solverStatus=nodes>=limit?"SEARCH_LIMIT_REACHED":"UNSOLVED";c.status=nodes>=limit?"SEARCH_LIMIT":"VALID_UNSOLVED";return c;}var gestures=new List<TraceGestureV1>();for(var n=win;n.parent!=null;n=n.parent)gestures.Add(new TraceGestureV1{habitatId=n.move.habitatId,press=new FloatPair{x=n.move.press.x,y=n.move.press.y},boardPath=n.move.path.Select(p=>new FloatPair{x=p.x,y=p.y}).ToArray(),checkpoint=SolutionTraceRunner.Fingerprint(n.state)});gestures.Reverse();var trace=new SolutionTraceV1{levelId=c.project.level.id,catalogFingerprint=c.project.sourceCatalogFingerprint,gestures=gestures.ToArray()};string error;if(!R10Solver.Replay(trace,c.project.level,rules,c.project.sourceCatalogFingerprint,out error)){c.solverStatus="UNSOLVED_REPLAY";c.status="VALID_UNSOLVED";return c;}c.trace=trace;c.solutionLength=gestures.Count;c.solverStatus="SOLVED";c.status="VALID_SOLVED";return c;}
} }
